 87	   * `clock_timestamp()`. `current_timestamp` is TRANSACTION start time, so a
 88	   * revocation whose transaction opened before the cutoff but committed after
 89	   * it would record an `updated_at` below the cutoff, slip under the fence, and
 90	   * be overwritten as fresh — the precise race the fence exists to stop. Both
 91	   * sides have to measure the same clock.
 92	   */
 93	  const rows = await getDb()<{ acl_support: string }>`
 94			INSERT INTO authz_source_acl_state
 95				(organization_id, connection_id, acl_support, freshness_state, updated_at)
 96			VALUES (${params.organizationId}, ${params.connectionId}, 'none', 'stale', clock_timestamp())
 97			ON CONFLICT (organization_id, connection_id)
 98			DO UPDATE SET freshness_state = 'stale', updated_at = clock_timestamp()
 99			RETURNING acl_support
100		`;
101	  // The upsert always yields a row, so a boolean "did it work" would be a
102	  // constant. Report the resulting support level instead — 'full' means an
103	  // already-enforcing connection went stale, 'none' means this revocation is
104	  // what onboarded it.
105	  return { aclSupport: rows[0].acl_support };
