101	  // Lock the whole group in one global order before applying any member. Pairwise
102	  // locking inside the loop is not sufficient: overlapping groups with different
103	  // winners can otherwise each hold one entity while waiting for the other.
104	  const entityIds = [...loserIds, params.winnerId].sort((a, b) => a - b);
105	  await tx`
106	    SELECT id
107	    FROM entities
108	    WHERE organization_id = ${params.orgId}
109	      AND id = ANY(${pgBigintArray(entityIds)}::bigint[])
110	    ORDER BY id
111	    FOR UPDATE
