117				winnerId: params.winnerId,
118				loserIds,
119				expectedFingerprint: params.expectedResolutionFingerprint,
120				// Computed by this process moments ago, so it is current by
121				// construction — never a stored digest from an older format.
122				expectedVersion: RESOLUTION_FINGERPRINT_VERSION,
123			});
