171	    id: number;
172	    entity_type_id: number;
173	    merged_into: number | null;
174	    deleted_at: string | null;
175			name: string;
176			metadata: Record<string, unknown>;
177			field_controls: Record<string, unknown>;
178	  }>`
179	    SELECT id, entity_type_id, merged_into, deleted_at, name, metadata, field_controls
180	    FROM entities
181	    WHERE organization_id = ${orgId} AND id IN (${a}, ${b})
