     1	/**
     2	 * NER-Lite Auto-Linker
     3	 *
     4	 * Scans event content for entity name mentions and creates
     5	 * `mentions` relationships automatically. Fire-and-forget pattern.
     6	 */
     7	
     8	import { getDb } from '../db/client';
     9	import { ensureRelationshipType, upsertEdges } from './edge-writes';
    10	import logger from './logger';
    11	
    12	interface AutoLinkParams {
    13	  eventId: number;
    14	  entityIds: number[];
    15	  content: string;
    16	  title?: string | null;
    17	  organizationId: string;
    18	}
    19	
    20	interface EntityCandidate {
    21	  id: number;
    22	  name: string;
    23	  entity_type: string;
    24	}
    25	
    26	// Per-org entity name cache (60s TTL)
    27	const entityCache = new Map<string, { entities: EntityCandidate[]; ts: number }>();
    28	const CACHE_TTL_MS = 60_000;
    29	const MAX_CONTENT_LENGTH = 5_000;
    30	const MAX_AUTO_LINKS = 20;
    31	const MIN_NAME_LENGTH = 3;
    32	
    33	async function getOrgEntities(organizationId: string): Promise<EntityCandidate[]> {
    34	  const cached = entityCache.get(organizationId);
    35	  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) return cached.entities;
    36	
    37	  const sql = getDb();
    38	  const rows = await sql`
    39	    SELECT e.id, e.name, et.slug AS entity_type
    40	    FROM entities e
    41	    JOIN entity_types et ON et.id = e.entity_type_id
    42	    WHERE e.organization_id = ${organizationId}
    43	      AND e.deleted_at IS NULL
    44	      AND length(e.name) >= ${MIN_NAME_LENGTH}
    45	    ORDER BY length(e.name) DESC
    46	  `;
    47	
    48	  const entities = rows.map((r) => ({
    49	    id: Number(r.id),
    50	    name: r.name as string,
    51	    entity_type: r.entity_type as string,
    52	  }));
    53	
    54	  entityCache.set(organizationId, { entities, ts: Date.now() });
    55	  return entities;
    56	}
    57	
    58	function ensureMentionsType(organizationId: string): Promise<number> {
    59	  return ensureRelationshipType({
    60	    organizationId,
    61	    slug: 'mentions',
    62	    name: 'Mentions',
    63	    description: 'Auto-discovered content reference',
    64	  });
    65	}
    66	
    67	/**
    68	 * Scan content for entity name mentions and create relationships.
    69	 */
    70	export async function autoLinkEvent(params: AutoLinkParams): Promise<void> {
    71	  const { entityIds, content, title, organizationId } = params;
    72	  if (!content && !title) return;
    73	
    74	  const allEntities = await getOrgEntities(organizationId);
    75	  const sourceSet = new Set(entityIds);
    76	
    77	  // Combine title + content, cap length
    78	  const searchText = [title, content].filter(Boolean).join(' ').slice(0, MAX_CONTENT_LENGTH);
    79	
    80	  const matched = new Set<number>();
    81	  const candidates: { fromId: number; toId: number }[] = [];
    82	
    83	  for (const entity of allEntities) {
