    20	import { type DbClient, getDb, pgBigintArray } from '../db/client';
    21	import type { RelationshipTypePurpose } from './relationship-validation';
    22	
    23	interface EdgePair {
    24	  fromEntityId: number;
    25	  toEntityId: number;
    26	}
    27	
    28	interface UpsertEdgesParams {
    29	  db: DbClient;
    30	  organizationId: string;
    31	  relationshipTypeId: number;
    32	  pairs: EdgePair[];
    33	  source: string;
    34	  confidence?: number | null;
    35	  createdBy?: string | null;
    36	  metadata?: object | null;
    37	  onConflict: 'ignore' | 'update';
    38	}
    39	
    40	/**
    41	 * Find-or-create an org-scoped relationship type.
    42	 *
    43	 * `description` only lands on first create; an existing type keeps its current
    44	 * description.
    45	 *
    46	 * `purpose` classifies the type for the ACL readers. Passing it also REPAIRS an
    47	 * existing row, which matters because this statement adopts rather than
    48	 * create-or-fails: without the repair, a row that predates the classification
    49	 * (or that an older pod created mid-rollout) would stay unclassified forever and
    50	 * its members would lose access once reads require it. Omitting `purpose` never
    51	 * clears an existing one — `mentions` and `member_of` share this function, and a
    52	 * mentions upsert must not strip an authorization stamp.
    53	 */
    54	export async function ensureRelationshipType(params: {
    55	  organizationId: string;
    56	  slug: string;
    57	  name: string;
    58	  description: string;
    59	  purpose?: RelationshipTypePurpose;
    60	}): Promise<number> {
    61	  const sql = getDb();
    62	  const rows = await sql<{ id: number }>`
    63	    INSERT INTO entity_relationship_types
    64	      (slug, name, description, organization_id, is_symmetric, created_by, purpose, created_at, updated_at)
    65	    VALUES
    66	      (${params.slug}, ${params.name}, ${params.description}, ${params.organizationId},
    67	       false, NULL, ${params.purpose ?? null}, current_timestamp, current_timestamp)
    68	    ON CONFLICT (organization_id, slug) WHERE status = 'active'
    69	    DO UPDATE SET
    70	      updated_at = EXCLUDED.updated_at,
    71	      purpose = COALESCE(EXCLUDED.purpose, entity_relationship_types.purpose)
    72	    RETURNING id
    73	  `;
    74	  return Number(rows[0].id);
    75	}
