    77	/**
    78	 * Write directed edges of one type in a single statement. In `ignore` mode the
    79	 * returned ids are newly created rows; in `update` mode they are created or
    80	 * refreshed rows.
    81	 */
    82	export async function upsertEdges(params: UpsertEdgesParams): Promise<number[]> {
    83	  const { db, organizationId, relationshipTypeId, source, onConflict } = params;
    84	
    85	  // `ON CONFLICT DO UPDATE` cannot affect the same row twice in one statement.
    86	  // Self-edges are dropped rather than written: identity resolution can collapse
    87	  // two source keys onto one entity, and a self-loop is meaningless for every
    88	  // type written here.
    89	  const seen = new Set<string>();
    90	  const pairs: EdgePair[] = [];
    91	  for (const pair of params.pairs) {
    92	    if (pair.fromEntityId === pair.toEntityId) continue;
    93	    const key = `${pair.fromEntityId}:${pair.toEntityId}`;
    94	    if (seen.has(key)) continue;
    95	    seen.add(key);
    96	    pairs.push(pair);
    97	  }
    98	  if (pairs.length === 0) return [];
    99	
   100	  const froms = pairs.map((p) => p.fromEntityId);
   101	  const tos = pairs.map((p) => p.toEntityId);
   102	
   103	  const conflictAction =
   104	    onConflict === 'update'
   105	      ? db`DO UPDATE SET
   106	            metadata = EXCLUDED.metadata,
   107	            source = EXCLUDED.source,
   108	            updated_by = EXCLUDED.updated_by,
   109	            updated_at = current_timestamp`
   110	      : db`DO NOTHING`;
   111	
   112	  const written = await db<{ id: number }>`
   113	    INSERT INTO entity_relationships (
   114	      organization_id, from_entity_id, to_entity_id, relationship_type_id,
   115	      metadata, confidence, source, created_by, updated_by, created_at, updated_at
   116	    )
   117	    SELECT
   118	      ${organizationId}, v.f, v.t, ${relationshipTypeId},
   119	      ${params.metadata == null ? null : db.json(params.metadata)},
   120	      ${params.confidence ?? null}, ${source},
   121	      ${params.createdBy ?? null}, ${params.createdBy ?? null},
   122	      current_timestamp, current_timestamp
   123	    FROM unnest(${pgBigintArray(froms)}::bigint[], ${pgBigintArray(tos)}::bigint[]) AS v(f, t)
   124	    ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
   125	      WHERE deleted_at IS NULL
   126	    ${conflictAction}
   127	    RETURNING id
   128	  `;
   129	
   130	  return written.map((row) => Number(row.id));
   131	}
